      readonly rental_status: string | null;
      /**
       * Speed Limit (Mbit/s)
       * @description Bandwidth cap in Mbit/s applied across all connections for a user on this package. Set to 0 for unlimited.
       */
      speed_limit?: number;
      /** Format: date-time */
